package ge.opensoft.openservice;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
final class WorkSearchBrowserAcceptance {
 static void run(BrowserTest h) throws Exception {String key="FindWork"+Values.id(),id=WorkSearchAcceptance.seed(h.store,key);try(var p=Playwright.create();var b=p.chromium().launch();var c=b.newContext()){var page=c.newPage();h.login(page,"admin");page.navigate(h.base()+"/admin/operations");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Search all retained work")).press("Enter");page.getByLabel("Job ID or deduplication key").fill(key);page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Find work")).click();for(String theme:new String[]{"light","dark"}){if(theme.equals("dark")){page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Dark mode").setExact(true)).click();page.setViewportSize(390,844);}assertThat(page.locator("main")).containsText("1 job");ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/work-search-"+theme+".png")).setFullPage(true));}page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Cancel").setExact(true)).press("Enter");assertThat(page.getByLabel("Job ID or deduplication key")).hasValue(key);assertThat(page.locator("tbody")).containsText("cancelled");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName(id).setExact(true)).press("Enter");assertThat(page.getByRole(AriaRole.HEADING,new Page.GetByRoleOptions().setName("Background work details"))).isVisible();ReleaseBrowserAcceptance.accessible(page);}}
}
